-- How do recorded closure rates compare across boroughs?
-- Bind %s parameters via mysql.connector.
WITH filtered AS (SELECT * FROM service_requests), valid AS (SELECT * FROM filtered WHERE created_date IS NOT NULL AND closed_date >= created_date AND resolution_hours >= 0), ranked AS (SELECT resolution_hours,ROW_NUMBER() OVER (ORDER BY resolution_hours) rn,COUNT(*) OVER () n FROM valid), fences AS (SELECT SUM(CASE WHEN rn=FLOOR((n-1)*0.25)+1 THEN resolution_hours*(1-((n-1)*0.25-FLOOR((n-1)*0.25))) WHEN rn=FLOOR((n-1)*0.25)+2 THEN resolution_hours*((n-1)*0.25-FLOOR((n-1)*0.25)) END) q1,SUM(CASE WHEN rn=FLOOR((n-1)*0.75)+1 THEN resolution_hours*(1-((n-1)*0.75-FLOOR((n-1)*0.75))) WHEN rn=FLOOR((n-1)*0.75)+2 THEN resolution_hours*((n-1)*0.75-FLOOR((n-1)*0.75)) END) q3 FROM ranked) SELECT borough,COUNT(*) request_count,SUM(is_closed) recorded_closed,100.0*SUM(is_closed)/COUNT(*) closure_pct FROM filtered GROUP BY borough ORDER BY closure_pct DESC;
